 "content": "from collections import Counter


def transform(grid):
    """Copy the populated panel's pattern to every equal-sized panel."""
    h, w = len(grid), len(grid[0])
    # Divider color is the color forming complete separator rows/columns.
    divider = None
    for color in range(10):
        if any(all(v == color for v in row) for row in grid) or any(
            all(grid[r][c] == color for r in range(h)) for c in range(w)
        ):
            divider = color
            break
    if divider is None:
        return [row[:] for row in grid]

    sep_rows = [r for r in range(h) if all(v == divider for v in grid[r])]
    sep_cols = [c for c in range(w) if all(grid[r][c] == divider for r in range(h))]

    def segments(length, separators):
        out, start = [], 0
        for pos in separators:
            if start < pos:
                out.append((start, pos))
            start = pos + 1
        if start < length:
            out.append((start, length))
        return out

    row_spans = segments(h, sep_rows)
    col_spans = segments(w, sep_cols)
    non_divider = [grid[r][c] for r in range(h) for c in range(w) if grid[r][c] != divider]
    background = Counter(non_divider).most_common(1)[0][0]

    panels = [(rs, cs) for rs in row_spans for cs in col_spans]
    source = None
    for rs, cs in panels:
        if any(grid[r][c] != background for r in range(*rs) for c in range(*cs)):
            source = (rs, cs)
            break
    if source is None:
        return [row[:] for row in grid]

    srs, scs = source
    pattern = [[grid[r][c] for c in range(*scs)] for r in range(*srs)]
    out = [row[:] for row in grid]
    for rs, cs in panels:
        if (rs[1] - rs[0], cs[1] - cs[0]) != (len(pattern), len(pattern[0])):
            continue
        for dr in range(len(pattern)):
            for dc in range(len(pattern[0])):
                out[rs[0] + dr][cs[0] + dc] = pattern[dr][dc]
    return out
